// src/pages/gov/DonationsQueryPage.jsx
import { useEffect, useMemo, useState }   from "react";
import { useToast }   from "../../context/ToastContext";
import { useAuth }    from "../../context/AuthContext";
import PageHeader     from "../../components/shared/PageHeader";
import DataTable      from "../../components/shared/DataTable";
import { donorApi, fundApi }    from "../../services/api";

const fmt   = (n) => n?.toLocaleString() ?? "–";
const short = (s) => s?.length > 12 ? s.slice(0,12)+"…" : s;

export default function DonationsQueryPage() {
  const toast = useToast();
  const { user } = useAuth();
  const [userCert, setUserCert] = useState(user?.userCert || "");
  const [donorId,  setDonorId]  = useState("");
  const [donorList, setDonorList] = useState([]);
  const [donorDetails, setDonorDetails] = useState(null);
  const [loadingDonors, setLoadingDonors] = useState(false);
  const [results,  setResults]  = useState(null);
  const [loading, setLoading] = useState(false);

  const selectedDonor = useMemo(
    () => donorList.find((item) => String(item?.donorId || "").trim() === String(donorId || "").trim()) || null,
    [donorList, donorId]
  );

  const loadDonors = async () => {
    if (!userCert) return;
    setLoadingDonors(true);
    try {
      const res = await donorApi.getAll({ userCert });
      const list = Array.isArray(res?.data) ? res.data : [];
      setDonorList(list);
      if (!donorId && list.length > 0) {
        setDonorId(String(list[0]?.donorId || "").trim());
      }
    } catch (err) {
      setDonorList([]);
      toast(err?.response?.data?.error || err.message || "Failed to load donor list", "error");
    } finally {
      setLoadingDonors(false);
    }
  };

  const loadDonorDetails = async (targetDonorId = donorId) => {
    if (!userCert || !targetDonorId) {
      setDonorDetails(null);
      return;
    }

    try {
      const res = await donorApi.getDonor({ userCert, donorId: targetDonorId });
      const data = res?.data?.data ?? res?.data;
      setDonorDetails(data || null);
    } catch (err) {
      setDonorDetails(selectedDonor || null);
      if (!selectedDonor) {
        toast(err?.response?.data?.error || err.message || "Failed to load donor details", "error");
      }
    }
  };

  useEffect(() => {
    if (userCert) {
      loadDonors();
    }
  }, [userCert]);

  useEffect(() => {
    if (donorId) {
      loadDonorDetails(donorId);
    }
  }, [donorId]);

  const query = async () => {
    if (!userCert || !donorId) {
      toast("UserCert and Donor ID are required", "error");
      return;
    }
    setLoading(true);
    try {
      const res = await fundApi.getByDonor(donorId, { userCert });
      const data = res.data || [];
      const flattened = data.flatMap((fundRecord) =>
        (fundRecord.donations || []).map((donation, idx) => ({
          id: `${fundRecord.fundId}-${idx + 1}`,
          donorId: donation.donorId,
          fundId: fundRecord.fundId,
          ngoId: fundRecord.ngoId,
          amount: Number(donation.amount || 0),
          tokenId: donation.tokenId,
          timestamp: donation.timestamp,
        }))
      );
      setResults(flattened);
      toast(`Found ${flattened.length} donation(s)`, "info");
    } catch (err) {
      toast(err?.response?.data?.error || err.message || "Query failed", "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <PageHeader title="Donations Query" desc="Look up all donations made by a specific donor" />

      <div className="card" style={{ marginBottom:16 }}>
        <div style={{ display:"flex", gap:12, alignItems:"flex-end", flexWrap:"wrap" }}>
          <div className="form-group" style={{ flex:1, minWidth:180 }}>
            <label>User Cert</label>
            <input value={userCert} onChange={(e) => setUserCert(e.target.value)} placeholder="govUserTom" />
          </div>
          <div className="form-group" style={{ flex:1, minWidth:180 }}>
            <label>Select Donor</label>
            <select value={donorId} onChange={(e) => setDonorId(e.target.value)} disabled={loadingDonors || donorList.length === 0}>
              <option value="">Select donor...</option>
              {donorList.map((item) => {
                const id = String(item?.donorId || "").trim();
                const name = String(item?.name || "").trim();
                return (
                  <option key={id || name} value={id}>
                    {id}{name ? ` - ${name}` : ''}
                  </option>
                );
              })}
            </select>
          </div>
          <button className="btn btn-secondary" onClick={loadDonors} disabled={loadingDonors || !userCert}>
            {loadingDonors ? "Refreshing..." : "Refresh Donor List"}
          </button>
          <button className="btn btn-primary" onClick={query} disabled={loading}>{loading ? "Querying..." : "Query Ledger"}</button>
        </div>
      </div>

      <div className="grid-2" style={{ marginBottom: 16 }}>
        <div className="card">
          <div className="card-title" style={{ marginBottom: 12 }}>Donor Details</div>
          {!donorId || !donorDetails ? (
            <div className="text-dim">Select a donor to view full details.</div>
          ) : (
            <div style={{ display: 'grid', gap: 10 }}>
              <div><strong>Donor ID:</strong> {donorDetails.donorId || donorId}</div>
              <div><strong>Name:</strong> {donorDetails.name || '—'}</div>
              <div><strong>Email:</strong> {donorDetails.email || '—'}</div>
              <div><strong>Alias:</strong> {donorDetails.alias || '—'}</div>
              <div><strong>User Cert:</strong> {donorDetails.userCert || '—'}</div>
            </div>
          )}
        </div>
        <div className="card">
          <div className="card-title" style={{ marginBottom: 12 }}>Selected Donor Summary</div>
          <div style={{ display: 'grid', gap: 10 }}>
            <div><strong>Selected:</strong> {selectedDonor ? `${selectedDonor.donorId}${selectedDonor.name ? ` - ${selectedDonor.name}` : ''}` : '—'}</div>
            <div><strong>Total Donors Loaded:</strong> {donorList.length}</div>
          </div>
        </div>
      </div>

      {results !== null && (
        <div className="card">
          <div className="card-title" style={{ marginBottom:16 }}>Results · {results.length} record(s)</div>
          <DataTable
            columns={[
              { key:"id",     label:"ID",      mono:true },
              { key:"donorId",label:"Donor",   mono:true },
              { key:"fundId", label:"Fund",    mono:true },
              { key:"ngoId",  label:"NGO",     mono:true },
              { key:"amount", label:"Amount",  render:(r) => <><span className="text-gold">◈</span> {fmt(r.amount)}</> },
              { key:"tokenId",label:"Token",   mono:true, render:(r) => short(r.tokenId) },
              { key:"timestamp", label:"Date", mono:true },
            ]}
            data={results}
            emptyText="No donations match this query"
          />
        </div>
      )}
    </div>
  );
}
